/* ══════════════════════════════════════════════════════════════════════
   State
   ══════════════════════════════════════════════════════════════════════ */
const pick = () => {
  try {
    const saved = localStorage.getItem('tg.lang');
    if (LANGS.some(l => l.id === saved)) return saved;
  } catch {}
  const nav = (navigator.language || 'en').slice(0, 2);
  return LANGS.some(l => l.id === nav) ? nav : 'en';
};

let activeLang = pick();
const listeners = new Set();

export const lang = () => activeLang;
/** A phrase in a given language, whatever the page is showing (the admin's EN / FR / AR fields). */
export const tIn = (l, key) => STR[l]?.[key] ?? STR.en[key] ?? key;
export const langInfo = () => LANGS.find(l => l.id === activeLang);
export const isRTL = () => langInfo().dir === 'rtl';
export const onLang = fn => listeners.add(fn);

export function applyLang() {
  const info = langInfo();
  document.documentElement.lang = info.id;
  document.documentElement.dir = info.dir;
}

export function setLang(id) {
  if (!LANGS.some(l => l.id === id) || id === activeLang) return;
  activeLang = id;
  try { localStorage.setItem('tg.lang', id); } catch {}
  applyLang();
  listeners.forEach(fn => fn(id));
}

/* ══════════════════════════════════════════════════════════════════════
   Lookups
   ══════════════════════════════════════════════════════════════════════ */
const fill = (s, vars) => vars ? s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '') : s;

export const t = (key, vars) => fill(TEXTS[key]?.[activeLang] ?? STR[activeLang][key] ?? TEXTS[key]?.en ?? STR.en[key] ?? key, vars);
/** Every phrase key, for the admin's Texts page. */
export const textKeys = () => Object.keys(STR.en);

export function plural(key, n) {
  const forms = PLURAL[activeLang][key] || PLURAL.en[key];
  const rule = new Intl.PluralRules(langInfo().locale).select(n);
  return fill(forms[rule] ?? forms.other, { n: n.toLocaleString('en-US') });
}

/** Prices are whole dinars: "180 DT" in English and French, "180 د.ت" in Arabic. */
/** The price in Tunisian dinars, the currency every payment is taken in. */
export const priceTND = n => {
  // whole dinars as "180 DT"; amounts with millimes (payment fees) as "393.90 DT"
  const opts = Number.isInteger(n) ? {} : { minimumFractionDigits: 2, maximumFractionDigits: 3 };
  return activeLang === 'ar'
    ? `${n.toLocaleString('en-US', opts)} د.ت`
    : `${n.toLocaleString(activeLang === 'fr' ? 'fr-FR' : 'en-US', opts)} DT`;
};

/* ── the shopper's display currency ───────────────────────────────────
   Prices can be shown in another currency at the owner's rate, marked "≈"
   because the payment is taken in dinars. The admin always shows dinars. */
const CUR_KEY = 'tg.currency';
let currency = (() => { try { return localStorage.getItem(CUR_KEY) || 'TND'; } catch { return 'TND'; } })();
let basePrices = false;
export const setBasePrices = on => { basePrices = !!on; };
export const currencies = () => ['TND', ...Object.keys(CURRENCY_RATES)];
export const currencyNow = () => (currency !== 'TND' && CURRENCY_RATES[currency] ? currency : 'TND');
export function setCurrency(c) {
  if (!currencies().includes(c) || c === currencyNow()) return;
  currency = c;
  try { localStorage.setItem(CUR_KEY, c); } catch {}
  listeners.forEach(fn => fn(activeLang));   // redraw like a language change
  refreshRates();
}

/* ── live exchange rates ──────────────────────────────────────────────
   Currencies the owner leaves on "Live" follow today's rate from
   open.er-api.com (free, no key, base TND), fetched only once a shopper
   picks another currency and kept on this device for 6 hours. Currencies
   set to "Manual", or any rate the service can't give, use the owner's rate. */
const RATES_URL = 'https://open.er-api.com/v6/latest/TND';
const RATES_KEY = 'tg.rates', RATES_TTL = 6 * 3600e3;
let live = (() => {
  try { const v = JSON.parse(localStorage.getItem(RATES_KEY)); return v && typeof v.at === 'number' && v.rates && typeof v.rates === 'object' ? v : null; }
  catch { return null; }
})();
let loading = null;
const liveOf = c => { const v = live?.rates[c]; return typeof v === 'number' && v > 0 ? v : 0; };
/** Is this currency priced at the live rate right now? */
export const rateIsLive = c => !RATE_MANUAL.includes(c) && liveOf(c) > 0;
/** 1 TND in currency c: the live rate, or the owner's. */
export const rateOf = c => (rateIsLive(c) ? liveOf(c) : CURRENCY_RATES[c]);
/** { rate, updated } from the service for c, whatever mode it is in. */
export const liveRate = c => (liveOf(c) ? { rate: liveOf(c), updated: live.updated || live.at } : null);
/** Fetch today's rates when they are older than 6 hours (or always, with force).
    Resolves true when new rates arrived, false when the service failed, null when nothing was needed. */
export function refreshRates(force = false) {
  if (!force && live && Date.now() - live.at < RATES_TTL) return Promise.resolve(null);
  if (!force && !Object.keys(CURRENCY_RATES).some(c => !RATE_MANUAL.includes(c))) return Promise.resolve(null);
  if (typeof fetch !== 'function') return Promise.resolve(false);
  return loading ??= fetch(RATES_URL, { cache: 'no-store', credentials: 'omit', referrerPolicy: 'no-referrer' })
    .then(r => (r.ok ? r.json() : Promise.reject(new Error(r.status))))
    .then(d => {
      if (d?.result !== 'success' || !d.rates || typeof d.rates !== 'object') throw new Error('bad rates');
      const rates = {};
      for (const [c, v] of Object.entries(d.rates)) if (/^[A-Z]{3}$/.test(c) && typeof v === 'number' && v > 0 && v < 1e7) rates[c] = v;
      const updated = Number(d.time_last_update_unix) * 1000;
      live = { at: Date.now(), updated: updated > 0 ? updated : Date.now(), rates };
      try { localStorage.setItem(RATES_KEY, JSON.stringify(live)); } catch {}
      if (currencyNow() !== 'TND') listeners.forEach(fn => fn(activeLang));
      return true;
    })
    .catch(() => false)
    .finally(() => { loading = null; });
}
export const price = n => {
  const c = currencyNow();
  if (basePrices || c === 'TND') return priceTND(n);
  const v = n * rateOf(c);
  const fmt = new Intl.NumberFormat(`${langInfo().locale}-u-nu-latn`, { style: 'currency', currency: c, minimumFractionDigits: v >= 100 ? 0 : 2, maximumFractionDigits: v >= 100 ? 0 : 2 });
  return `≈ ${fmt.format(v)}`;
};
/** Plain numbers in the same style as prices (French comma, Latin digits elsewhere). */
export const num = n => n.toLocaleString(activeLang === 'fr' ? 'fr-FR' : 'en-US');

export const date = ts => new Date(ts).toLocaleDateString(langInfo().locale, {
  day: 'numeric', month: 'short', year: 'numeric', numberingSystem: 'latn'
});

/** A tag, spec or badge in the activeLang language (brand names pass through). */
export function word(w) {
  if (activeLang === 'en' || !VOCAB[w]) return w;
  return VOCAB[w][activeLang === 'fr' ? 0 : 1];
}

export function blurb(p) {
  if (p.custom && p.blurb) return p.blurb;   // written by the store owner in the admin
  if (BLURB[activeLang]?.[p.id]) return BLURB[activeLang][p.id];
  if (p.blurb) return p.blurb;   // English original
  if (p.game) {   // a game version: its platform, as a key or an account
    const account = p.delivery === 'account' || (!p.delivery && p.tags.some(x => /account/i.test(x)));
    return fill(TEMPLATE[activeLang][account ? 'gameAccount' : 'gameKey'], { name: p.short, platform: t('plat.' + (p.platform || 'pc')) });
  }
  const kind = p.delivery === 'ship' || p.cat === 'hardware' ? 'ship' : TEMPLATE_FOR[p.tags[1]] || 'credit';
  return fill(TEMPLATE[activeLang][kind], { name: p.short });
}

export const faq = (l = activeLang) => (FAQ_OVR[l]?.length ? FAQ_OVR[l] : FAQ[l]);
/** The questions and answers as shipped, for the admin to start from. */
export const faqShipped = l => FAQ[l];
